//! Wire adapter; business logic is supplied by the corresponding internal DLL.
use serde::{Serialize,Deserialize};use serde_json::{json,Value};use std::{path::PathBuf,collections::HashMap};
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(rename_all="camelCase")]
pub struct Todo{pub id:String,pub title:String,pub content:String,pub date:String,pub time:String,pub daily:bool,#[serde(default="default_color")]pub color:String,#[serde(default)]pub completed:bool,#[serde(default)]pub completed_date:Option<String>,#[serde(default)]pub last_reminded_date:Option<String>,#[serde(default)]pub snooze_until:Option<String>}
#[derive(Clone,Debug,Serialize,Deserialize)]pub struct Now{pub date:String,pub time:String}
fn request<T:serde::de::DeserializeOwned>(method:&str,args:Value)->Result<T,String>{serde_json::from_value(dotisle_module_api::call("todos",method,args)?).map_err(|e|e.to_string())}
pub fn default_color()->String{request("default_color",json!({})).unwrap_or_else(|_|"#F3D79B".into())}
impl Now{pub fn local()->Self{request("now",json!({})).expect("todo time service unavailable")}}
impl Todo{pub fn done(&self,now:&Now)->bool{request("done",json!({"todo":self,"now":now})).unwrap_or(false)}}
pub fn valid_date(s:&str)->bool{request("valid_date",json!({"text":s})).unwrap_or(false)}
pub fn valid_time(s:&str)->bool{request("valid_time",json!({"text":s})).unwrap_or(false)}
pub fn add_minutes(date:&str,time:&str,minutes:u32)->String{request("add_minutes",json!({"date":date,"time":time,"minutes":minutes})).unwrap_or_default()}
pub struct Store {session:dotisle_module_api::Session,pub items:Vec<Todo>,pub error:Option<String>}
impl Store{
pub fn new(path:PathBuf)->Self{let (session,reply)=dotisle_module_api::Session::new("todos","store",json!({"path":path}));let mut this=Self{session,items:Default::default(),error:Default::default()};match reply{Ok(v)=>this.sync(&v),Err(e)=>this.error=Some(e)};this}
fn sync(&mut self,v:&Value){if let Ok(value)=serde_json::from_value(v["items"].clone()){self.items=value;}if let Ok(value)=serde_json::from_value(v["error"].clone()){self.error=value;}}
fn args(&self,mut a:Value)->Value{a["items"]=json!(self.items);a}
fn invoke(&mut self,method:&str,args:Value)->Result<Value,String>{let reply=self.session.invoke(method,self.args(args));let v=match reply{Ok(v)=>v,Err(e)=>{self.error=Some(e.clone());return Err(e)}};self.sync(&v);if let Some(e)=v["operationError"].as_str(){return Err(e.into());}Ok(v["result"].clone())}
pub fn list(&self,n:&Now)->Value{let value=self.session.invoke("list",self.args(json!({"now":n}))).and_then(|v|{if let Some(e)=v["operationError"].as_str(){Err(e.into())}else{Ok(v["result"].clone())}});value.ok().and_then(|v|serde_json::from_value(v).ok()).unwrap_or_default()}
pub fn save(&mut self,v:&Value)->Result<String,String>{let value=self.invoke("save",json!({"v":v}));value.and_then(|v|serde_json::from_value(v).map_err(|e|e.to_string()))}
pub fn complete(&mut self,id:&str,done:bool,n:&Now)->Result<(),String>{let value=self.invoke("complete",json!({"id":id,"done":done,"now":n}));value.and_then(|v|serde_json::from_value(v).map_err(|e|e.to_string()))}
pub fn snooze(&mut self,id:&str,minutes:u32,n:&Now)->Result<(),String>{let value=self.invoke("snooze",json!({"id":id,"minutes":minutes,"now":n}));value.and_then(|v|serde_json::from_value(v).map_err(|e|e.to_string()))}
pub fn restore(&mut self,value:Todo)->Result<(),String>{let value=self.invoke("restore",json!({"v":value}));value.and_then(|v|serde_json::from_value(v).map_err(|e|e.to_string()))}
pub fn delete(&mut self,id:&str)->Result<(),String>{let value=self.invoke("delete",json!({"id":id}));value.and_then(|v|serde_json::from_value(v).map_err(|e|e.to_string()))}
pub fn poll(&mut self,n:&Now)->Result<Vec<Todo>,String>{let value=self.invoke("poll",json!({"now":n}));value.and_then(|v|serde_json::from_value(v).map_err(|e|e.to_string()))}
}

#[cfg(test)]mod tests{use super::*;fn fixture()->(Store,PathBuf){let p=std::env::temp_dir().join(format!("LyricIsland.TodoTest.{}.{}.json",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));(Store::new(p.clone()),p)}fn now(d:&str,t:&str)->Now{Now{date:d.into(),time:t.into()}}
 #[test]fn calendar_validation_including_leap_year(){assert!(valid_date("2028-02-29"));for d in ["2026-02-29","2026-13-01","2026-04-31","２０２６-01"]{assert!(!valid_date(d));}assert!(valid_time("09:03"));assert!(!valid_time("24:00"));}
 #[test]fn markers_survive_restart_and_daily_completion_resets_next_day(){let (mut s,p)=fixture();let id=s.save(&json!({"title":"喝水","content":"休息一下","date":"2026-10-16","time":"09:00","daily":true})).unwrap();assert!(s.poll(&now("2026-10-16","08:59")).unwrap().is_empty());assert_eq!(s.poll(&now("2026-10-16","09:00")).unwrap().len(),1);let mut s=Store::new(p.clone());assert!(s.poll(&now("2026-10-16","10:00")).unwrap().is_empty());s.complete(&id,true,&now("2026-10-16","10:00")).unwrap();assert!(!s.items[0].done(&now("2026-10-17","08:00")));assert_eq!(s.poll(&now("2026-10-17","09:00")).unwrap().len(),1);let _=std::fs::remove_file(p);}
 #[test]fn one_time_overdue_delivered_once_and_completed_never_alerts(){let (mut s,p)=fixture();let id=s.save(&json!({"title":"交稿","date":"2026-10-15","time":"09:00"})).unwrap();s.complete(&id,true,&now("2026-10-16","10:00")).unwrap();assert!(s.poll(&now("2026-10-16","10:00")).unwrap().is_empty());s.complete(&id,false,&now("2026-10-16","10:00")).unwrap();assert_eq!(s.poll(&now("2026-10-16","10:00")).unwrap().len(),1);assert!(s.poll(&now("2026-10-17","10:00")).unwrap().is_empty());let _=std::fs::remove_file(p);}
 #[test]fn corrupt_store_is_never_overwritten(){let p=std::env::temp_dir().join(format!("LyricIsland.CorruptTodos.{}.json",std::process::id()));std::fs::write(&p,b"broken").unwrap();let mut s=Store::new(p.clone());assert!(s.save(&json!({"title":"x","date":"2026-10-16","time":"09:00"})).is_err());assert_eq!(std::fs::read(&p).unwrap(),b"broken");let _=std::fs::remove_file(p);}
 #[test]fn snooze_delivers_once_then_never_again_and_completion_cancels(){let (mut s,p)=fixture();let id=s.save(&json!({"title":"交稿","date":"2026-10-15","time":"09:00"})).unwrap();s.snooze(&id,10,&now("2026-10-16","10:00")).unwrap();assert_eq!(s.items[0].snooze_until.as_deref(),Some("2026-10-16 10:10"));assert!(s.poll(&now("2026-10-16","10:05")).unwrap().is_empty());assert_eq!(s.poll(&now("2026-10-16","10:10")).unwrap().len(),1);assert!(s.poll(&now("2026-10-16","10:20")).unwrap().is_empty());s.snooze(&id,60,&now("2026-10-16","11:00")).unwrap();assert_eq!(s.items[0].snooze_until.as_deref(),Some("2026-10-16 12:00"));s.complete(&id,true,&now("2026-10-16","11:00")).unwrap();assert!(s.items[0].snooze_until.is_none());assert!(s.poll(&now("2026-10-16","12:05")).unwrap().is_empty());let _=std::fs::remove_file(p);}
 #[test]fn snooze_of_a_future_reminder_only_delays_its_own_moment(){let (mut s,p)=fixture();let id=s.save(&json!({"title":"取快递","date":"2026-10-16","time":"18:30"})).unwrap();s.snooze(&id,10,&now("2026-10-16","14:00")).unwrap();assert_eq!(s.items[0].snooze_until.as_deref(),Some("2026-10-16 18:40"));assert!(s.poll(&now("2026-10-16","18:30")).unwrap().is_empty());assert_eq!(s.poll(&now("2026-10-16","18:40")).unwrap().len(),1);assert!(s.poll(&now("2026-10-16","19:00")).unwrap().is_empty());let _=std::fs::remove_file(p);}
 #[test]fn cross_midnight_snooze_survives_restart_and_keeps_the_daily_cycle(){let (mut s,p)=fixture();let id=s.save(&json!({"title":"记日记","date":"2026-10-16","time":"23:55","daily":true})).unwrap();assert_eq!(s.poll(&now("2026-10-16","23:55")).unwrap().len(),1);s.snooze(&id,10,&now("2026-10-16","23:55")).unwrap();assert_eq!(s.items[0].snooze_until.as_deref(),Some("2026-10-17 00:05"));let mut s=Store::new(p.clone());assert!(s.poll(&now("2026-10-17","00:04")).unwrap().is_empty());assert_eq!(s.poll(&now("2026-10-17","00:05")).unwrap().len(),1);assert!(s.poll(&now("2026-10-17","00:06")).unwrap().is_empty());assert_eq!(s.poll(&now("2026-10-17","23:55")).unwrap().len(),1);let _=std::fs::remove_file(p);}
 #[test]fn snooze_rejects_unknown_delays_and_completed_items(){let (mut s,p)=fixture();let id=s.save(&json!({"title":"x","date":"2026-10-16","time":"09:00"})).unwrap();assert!(s.snooze(&id,30,&now("2026-10-16","09:00")).is_err());assert!(s.snooze("missing",10,&now("2026-10-16","09:00")).is_err());s.complete(&id,true,&now("2026-10-16","09:00")).unwrap();assert!(s.snooze(&id,10,&now("2026-10-16","09:00")).is_err());let _=std::fs::remove_file(p);}
 #[test]fn editing_the_schedule_cancels_a_pending_snooze(){let (mut s,p)=fixture();let id=s.save(&json!({"title":"x","date":"2026-10-16","time":"09:00"})).unwrap();s.snooze(&id,10,&now("2026-10-16","09:00")).unwrap();s.save(&json!({"id":id,"title":"x","date":"2026-10-16","time":"12:00"})).unwrap();assert!(s.items[0].snooze_until.is_none());assert_eq!(s.poll(&now("2026-10-16","12:00")).unwrap().len(),1);let _=std::fs::remove_file(p);}
 #[test]fn add_minutes_carries_days_months_and_leap_years(){assert_eq!(add_minutes("2026-10-16","23:55",10),"2026-10-17 00:05");assert_eq!(add_minutes("2026-10-31","23:55",60),"2026-11-01 00:55");assert_eq!(add_minutes("2026-12-31","23:30",60),"2027-01-01 00:30");assert_eq!(add_minutes("2028-02-28","23:55",10),"2028-02-29 00:05");assert_eq!(add_minutes("2027-02-28","23:55",10),"2027-03-01 00:05");}
}
